vulnerable_code:
const { createProxyMiddleware } = require('http-proxy-middleware');

app.use('/api/v1/billing', authenticateClient, (req, res, next) => {
  const targetTenantId = req.headers['x-tenant-id'] || req.query.tenantId;
  createProxyMiddleware({
    target: process.env.INTERNAL_BILLING_SERVICE_URL,
    changeOrigin: true,
    onProxyReq: (proxyReq) => {
      proxyReq.setHeader('x-forwarded-tenant', targetTenantId);
    }
  })(req, res, next);
});

corrected_code:
const { createProxyMiddleware } = require('http-proxy-middleware');

app.use('/api/v1/billing', authenticateClient, (req, res, next) => {
  const verifiedTenantId = req.user.tenantId;
  createProxyMiddleware({
    target: process.env.INTERNAL_BILLING_SERVICE_URL,
    changeOrigin: true,
    onProxyReq: (proxyReq) => {
      proxyReq.setHeader('x-forwarded-tenant', verifiedTenantId);
    }
  })(req, res, next);
});
